# Break My Fix finding 3, generated by Tracefix: Env.db_url returns a wrong value.
# Property (issue): db_url returns the same config as db_url_config applied to the value with the same engine/extra_options
# Quote: Perhaps they can be passed in a new `extra_options` argument?
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_3() -> None:
    self_after = Env()
    var = 'DJANGO_ENVIRON_UNSET_TEST_VAR_XYZ'
    default = 'postgres://user:pass@localhost:5432/db'
    engine = None
    options_cast = None
    extra_options = {'pool': {'min_size': 2, 'max_size': 4, 'timeout': 10}}
    # The property applies to this input: var == 'DJANGO_ENVIRON_UNSET_TEST_VAR_XYZ' and isinstance(default, str) and '://' in default and default.split('://')[0] in Env.DB_SCHEMES
    result = self_after.db_url(var=var, default=default, engine=engine, options_cast=options_cast, extra_options={'pool': {'min_size': 2, 'max_size': 4, 'timeout': 10}})
    assert (result == Env.db_url_config(default, engine=engine, options_cast=options_cast, extra_options=extra_options))
